var frames={bell:[{transform:'rotate(0)'},{transform:'rotate(-16deg)',offset:.2},{transform:'rotate(12deg)',offset:.4},{transform:'rotate(-8deg)',offset:.65},{transform:'rotate(0)'}],refresh:[{transform:'rotate(0)'},{transform:'rotate(360deg)'}],search:[{transform:'scale(1)'},{transform:'scale(1.13)',offset:.4},{transform:'scale(1)'}],book:[{transform:'perspective(100px) rotateY(0)'},{transform:'perspective(100px) rotateY(-24deg)',offset:.4},{transform:'perspective(100px) rotateY(0)'}],star:[{transform:'scale(1) rotate(0)'},{transform:'scale(1.15) rotate(12deg)',offset:.45},{transform:'scale(1) rotate(0)'}],gear:[{transform:'rotate(0)'},{transform:'rotate(60deg)'}],sun:[{transform:'rotate(0)'},{transform:'rotate(90deg)'}],moon:[{transform:'rotate(-15deg) scale(.9)'},{transform:'rotate(0) scale(1)'}],mail:[{transform:'translateY(0) rotate(0)'},{transform:'translateY(-3px) rotate(-7deg)',offset:.4},{transform:'translateY(0) rotate(0)'}],out:[{transform:'translateX(0)'},{transform:'translateX(3px)',offset:.5},{transform:'translateX(0)'}]};
